local function iso(dayOff, h, m)
  local t = os.date("*t", os.time() + dayOff * 86400)
  return string.format("%04d-%02d-%02dT%02d:%02d:00+05:30", t.year, t.month, t.day, h, m)
end
local function dkey(n)
  local t = os.date("*t", os.time() + n * 86400)
  return string.format("%04d-%02d-%02d", t.year, t.month, t.day)
end
